"use client";
import { useEffect, useState } from "react";
type Sale={id:string;receiptNo:string;totalAmount:number|string;payment:string;status:string;createdAt:string;employeeName:string};
export default function TransactionsPage(){const [q,setQ]=useState("");const [status,setStatus]=useState("");const [payment,setPayment]=useState("");const [rows,setRows]=useState<Sale[]>([]);const [message,setMessage]=useState("");const [loading,setLoading]=useState(true);async function load(){setLoading(true);const params=new URLSearchParams();if(q)params.set("search",q);if(status)params.set("status",status);if(payment)params.set("payment",payment);try{const r=await fetch(`/api/sales?${params}`);const d=await r.json();if(!r.ok)throw new Error(d.error||"Unable to load transactions");setRows(d.sales)}catch(e){setMessage(e instanceof Error?e.message:"Unable to load transactions")}finally{setLoading(false)}}useEffect(()=>{const t=setTimeout(load,250);return()=>clearTimeout(t)},[q,status,payment]);async function cancel(id:string){if(!confirm("Cancel this sale? Stock will be restored."))return;const r=await fetch("/api/sales",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id})});const d=await r.json();if(!r.ok){setMessage(d.error||"Unable to cancel sale");return}setMessage("Sale cancelled.");load()}return <main className="min-h-screen bg-[#0b0b0b] p-5 text-white md:p-8"><div className="mx-auto max-w-6xl"><h1 className="text-2xl font-semibold">Transactions</h1>{message&&<p className="mt-4 rounded-xl bg-white/5 p-3 text-sm text-orange-300">{message}</p>}<div className="mt-6 grid gap-3 md:grid-cols-3"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Search by receipt number..." className="field"/><select value={status} onChange={e=>setStatus(e.target.value)} className="field"><option value="">All statuses</option><option value="COMPLETED">Completed</option><option value="CANCELLED">Cancelled</option></select><select value={payment} onChange={e=>setPayment(e.target.value)} className="field"><option value="">All payment methods</option><option value="CASH">Cash</option><option value="TRANSFER">Transfer</option><option value="POS">POS</option></select></div><div className="mt-6 overflow-x-auto rounded-2xl border border-white/10 bg-[#151515] p-5"><table className="w-full text-left text-sm"><thead className="text-xs text-white/40"><tr>{["DATE","RECEIPT","AMOUNT","PAYMENT","STATUS","EMPLOYEE","ACTION"].map(x=><th key={x} className="px-3 py-3">{x}</th>)}</tr></thead><tbody>{loading?<tr><td colSpan={7} className="px-3 py-10 text-center text-white/30">Loading...</td></tr>:rows.map(r=><tr key={r.id} className="border-t border-white/5"><td className="px-3 py-4">{new Date(r.createdAt).toLocaleString()}</td><td className="px-3 py-4">{r.receiptNo}</td><td className="px-3 py-4">₦{Number(r.totalAmount).toLocaleString()}</td><td className="px-3 py-4">{r.payment}</td><td className="px-3 py-4"><span className={`rounded-full px-2 py-1 text-xs ${r.status==="COMPLETED"?"bg-green-500/10 text-green-400":"bg-red-500/10 text-red-400"}`}>{r.status}</span></td><td className="px-3 py-4">{r.employeeName}</td><td className="px-3 py-4">{r.status==="COMPLETED"&&<button onClick={()=>cancel(r.id)} className="text-red-400">Cancel</button>}</td></tr>)}{!loading&&!rows.length&&<tr><td colSpan={7} className="px-3 py-10 text-center text-white/30">No transactions found.</td></tr>}</tbody></table></div></div></main>}
